package stack

// Stack is a LIFO of ints.
type Stack struct{ xs []int }

// Push adds x.
func (s *Stack) Push(x int) { s.xs = append(s.xs, x) }

// Pop removes the last value; ok is false on an empty stack.
func (s *Stack) Pop() (int, bool) {
	if len(s.xs) == 0 {
		return 0, false
	}
	x := s.xs[len(s.xs)-1]
	s.xs = s.xs[:len(s.xs)-1]
	return x, true
}

