package stack

import "testing"

func TestPop(t *testing.T) {
	var s Stack
	if _, ok := s.Pop(); ok {
		t.Fatal("pop on an empty stack succeeded")
	}
	s.Push(1)
	s.Push(2)
	if x, ok := s.Pop(); !ok || x != 2 {
		t.Fatalf("pop = %d, %v", x, ok)
	}
}

